def graph_for(board, width):
    graph = {}
    for y in range(len(board)):
        for x in range(width):
            if board[y][x] == "#":
                continue
            neighbors = []
            for step in [[0,-1,"up"],[1,0,"right"],[0,1,"down"],[-1,0,"left"]]:
                nx = x + step[0]
                ny = y + step[1]
                if 0 <= nx and nx < width and 0 <= ny and ny < len(board) and board[ny][nx] == ".":
                    neighbors.append([ny * width + nx, step[2]])
            graph[y * width + x] = neighbors
    return graph

def routes(graph, cache, start):
    if start in cache:
        return cache[start]
    queue = [start]
    table = {start: [0, None]}
    for cell in queue:
        previous = table[cell]
        for edge in graph[cell]:
            neighbor = edge[0]
            if neighbor in table:
                continue
            first = previous[1]
            if first is None:
                first = edge[1]
            table[neighbor] = [previous[0] + 1, first]
            queue.append(neighbor)
    cache[start] = table
    return table

def steps_to(table, cell):
    if cell in table:
        return table[cell][0]
    return 999

def nearest_rival(rivals, cell):
    nearest = 999
    for rival in rivals:
        steps = steps_to(rival, cell)
        if steps < nearest:
            nearest = steps
    return nearest

def rival_routes(graph, cache, width, opponents):
    result = []
    for opponent in opponents:
        result.append(routes(graph, cache, opponent["y"] * width + opponent["x"]))
    return result

def separation(cell, width, opponent):
    dx = cell % width - opponent["x"]
    dy = cell // width - opponent["y"]
    if dx < 0:
        dx = -dx
    if dy < 0:
        dy = -dy
    return dx + dy

def choose_target(state, width, mine, rivals):
    if len(state["items"]) == 0:
        exit = state["exit"]
        return exit[1] * width + exit[0]
    chosen = None
    best_lead = -999
    best_steps = 999
    for item in state["items"]:
        cell = item["y"] * width + item["x"]
        if cell not in mine:
            continue
        steps = mine[cell][0]
        lead = nearest_rival(rivals, cell) - steps
        if chosen is None or lead > best_lead or (lead == best_lead and steps < best_steps):
            chosen = cell
            best_lead = lead
            best_steps = steps
    return chosen

def options(state, graph, width, start):
    legal = []
    for item in state["items"]:
        if item["y"] * width + item["x"] == start:
            legal.append([start, "pick"])
    for edge in graph[start]:
        legal.append(edge)
    return legal

def decide(state, width, graph, cache):
    opponents = state["opponents"]
    player = state["player"]
    start = player[1] * width + player[0]
    mine = routes(graph, cache, start)
    rivals = rival_routes(graph, cache, width, opponents)
    target = choose_target(state, width, mine, rivals)
    if target is None:
        return "wait"
    remaining = routes(graph, cache, target)
    chosen = "wait"
    best_risk = 999
    best_steps = 999
    best_room = -1
    for option in options(state, graph, width, start):
        cell = option[0]
        action = option[1]
        risk = 0
        room = 999
        for opponent in opponents:
            distance = separation(cell, width, opponent)
            if distance <= 1:
                risk += 1
            if distance < room:
                room = distance
        steps = steps_to(remaining, cell)
        if action == "pick" and cell == target:
            steps = -1
        if risk < best_risk or (risk == best_risk and (steps < best_steps or (steps == best_steps and room > best_room))):
            chosen = action
            best_risk = risk
            best_steps = steps
            best_room = room
    return chosen

state = scan()
board = state["tiles"]
width = len(board[0])
graph = graph_for(board, width)
cache = {}
while True:
    action = decide(state, width, graph, cache)
    if action == "pick":
        pick()
    elif action == "wait":
        wait()
    else:
        move(action)
    state = scan()
